    def segment(i1,j1,i2,j2,c):
        di=(i2-i1)//abs(i2-i1); dj=(j2-j1)//abs(j2-j1) if j1!=j2 else 0
        i,j=i1+di,j1+dj
        while (i,j)!=(i2,j2):
